{
  "name": "opencode-line-endings",
  "version": "0.2.0",
  "description": "OpenCode plugin that enforces consistent line endings (LF or CRLF) on file edits",
  "type": "module",
  "main": "index.ts",
  "exports": {
    ".": "./index.ts",
    "./server": "./server.ts"
  },
  "files": [
    "index.ts",
    "server.ts",
    "line-endings.ts",
    "COMPATIBILITY.md"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/CodingMarco/opencode-line-endings.git"
  },
  "bugs": {
    "url": "https://github.com/CodingMarco/opencode-line-endings/issues"
  },
  "homepage": "https://github.com/CodingMarco/opencode-line-endings#readme",
  "dependencies": {
    "editorconfig": "^3.0.2"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "line-endings",
    "crlf",
    "lf",
    "editorconfig",
    "wsl"
  ],
  "scripts": {
    "test": "node --test test/*.test.ts",
    "typecheck": "tsc --noEmit",
    "build": "npm run typecheck"
  },
  "license": "MIT",
  "devDependencies": {
    "@opencode-ai/plugin": "1.2.15",
    "@opencode/plugin": "2.0.24",
    "@types/node": "^25.3.3",
    "typescript": "^5.9.3"
  }
}
